<template><div class="app-container p-4"><h2>AI 审计与用量</h2><p>展示授权操作与执行元数据。用量来自供应商响应；费用按调用时的模型费率估算，不能替代账单。</p><el-radio-group v-model="category" @change="reset"><el-radio-button v-for="item in categories" :key="item[0]" :value="item[0]">{{item[1]}}</el-radio-button></el-radio-group><el-button :loading="loading" @click="load">刷新</el-button><el-alert v-if="error" :title="error" type="error" :closable="false"/><template v-if="category==='usage'"><p>近 <el-input-number v-model="days" :min="1" :max="90" :precision="0" @change="load"/> 天；不同币种分别统计，未知成本不计入已知估算合计。</p></template><div v-if="category==='core-usage'" class="flex gap-2 my-4"><el-input v-model="filterUser" placeholder="员工 ID（可选）"/><el-input v-model="filterModel" placeholder="模型 ID（可选）"/><el-input v-model="filterTask" placeholder="任务 / 会话 ID（可选）"/><el-button @click="reset">查询</el-button></div><el-table v-loading="loading" :data="rows" empty-text="当前没有记录"><el-table-column v-for="field in columns" :key="field" :prop="field" :label="labels[field]||field" :min-width="field.includes('id')?200:130" show-overflow-tooltip><template #default="{row}">{{display(row[field])}}</template></el-table-column></el-table><div v-if="category!=='usage'" class="mt-4"><el-button :disabled="page===1||loading" @click="page--;load()">上一页</el-button><span>第 {{page}} 页</span><el-button :disabled="rows.length<30||loading" @click="page++;load()">下一页</el-button></div><el-alert class="mt-4" title="未完成回执显示 INCOMPLETE；空用量和费用表示未知，不代表零消耗。旧版本未采集的调用不补造用量。" type="info" :closable="false"/></div></template>
<script setup lang="ts">
import request from '@/utils/request';
const categories=[['core-usage','员工 / 模型 / 任务用量'],['calls','模型 / MCP 调用'],['tools','工具 / 审批'],['knowledge','知识访问'],['files','文件访问'],['security','安全与资源操作'],['usage','用量汇总'],['legacy-usage','迁移用量'],['legacy-audit','迁移审计']];
const category=ref('core-usage'),rows=ref<Record<string,unknown>[]>([]),page=ref(1),days=ref(30),loading=ref(false),error=ref('');const filterUser=ref(''),filterModel=ref(''),filterTask=ref('');let generation=0;
const labels:Record<string,string>={conversation_id:'任务 / 会话 ID',call_id:'调用 ID',cost_status:'费用状态',sequence:'原序号',result:'原结果',request_id:'原请求 ID',prev_hash:'前序哈希',hash:'原签名',model_code:'模型代码',usage_reported:'供应商已报告用量',id:'记录 ID',run_id:'任务 ID',owner_user_id:'员工 ID',actor_user_id:'操作者 ID',kind:'调用类型',resource_id:'资源 ID',model_id:'模型 ID',provider_id:'Provider ID',status:'状态',input_tokens:'输入 Token',output_tokens:'输出 Token',estimated_cost:'估算费用',currency:'币种',duration_ms:'总耗时 ms',provider_ttfb_ms:'供应商 TTFB ms',first_token_ms:'模型首 Token ms',http_status:'HTTP 状态',created_at:'创建时间',finished_at:'结束时间',action:'操作',day:'日期',calls:'调用次数',incomplete_calls:'回执未完成',unknown_token_calls:'用量未知次数',unknown_cost_calls:'费用未知次数',known_input_tokens:'已知输入 Token',known_output_tokens:'已知输出 Token',known_estimated_cost:'已知估算费用合计'};
const columns=computed(()=>category.value==='calls'?['created_at','kind','status','input_tokens','output_tokens','duration_ms','estimated_cost','currency','provider_ttfb_ms','first_token_ms','http_status','owner_user_id','run_id','id','resource_id','model_id','provider_id','finished_at']:rows.value.length?Object.keys(rows.value[0]):['id','status','created_at']);const display=(v:unknown)=>v===null||v===undefined?'未知':typeof v==='boolean'?(v?'是':'否'):({STARTED:'执行中',COMPLETED:'已完成',FAILED:'失败',CANCELLED:'已取消',INCOMPLETE:'回执不完整',MODEL:'模型',MCP:'MCP'} as Record<string,string>)[String(v)]||String(v);
async function load(){const g=++generation;loading.value=true;error.value='';rows.value=[];try{const result=await request({url:category.value==='usage'?'/ai/admin/usage':category.value==='core-usage'?'/ai/admin/core-usage':'/ai/admin/audit',params:category.value==='usage'?{days:days.value}:category.value==='core-usage'?{page:page.value,userId:filterUser.value||undefined,modelId:filterModel.value||undefined,conversationId:filterTask.value||undefined}:{category:category.value,page:page.value}});if(g===generation)rows.value=result.data;}catch{if(g===generation)error.value='读取失败，请重试。';}finally{if(g===generation)loading.value=false;}}
function reset(){page.value=1;void load();}onMounted(load);
</script>
